// The English texts of upstream's forms (source/forms/*.dfm), generated by
// tools/dfm2cpp: the form, the path of the property of its component as the
// translations key it, the text.
//---------------------------------------------------------------------------
#ifndef FormTextsH
#define FormTextsH
//---------------------------------------------------------------------------
#include <cstddef>
//---------------------------------------------------------------------------
struct TFormText
{
  const wchar_t * Form;
  const wchar_t * Key;
  const wchar_t * Text;
};
//---------------------------------------------------------------------------
extern const TFormText FormTexts[];
extern const size_t FormTextCount;
//---------------------------------------------------------------------------
#endif
